class Solution {
    public int[] shuffle(int[] nums, int n) {
        int[] answer = new int[2 * n];
        for (int i = 0; i < n; i++) {
            answer[2 * i] = nums[i];
            answer[2 * i + 1] = nums[i + n];
        }
        return answer;
    }
}

class Solution {
    public int[] shuffle(int[] nums, int n) {
        int[] answer = new int[2 * n];
        int left = 0;
        int right = n;
        int write = 0;

        while (left < n) {
            answer[write++] = nums[left++];
            answer[write++] = nums[right++];
        }
        return answer;
    }
}

class Solution {
    public int[] shuffle(int[] nums, int n) {
        for (int i = 0; i < n; i++) {
            nums[i] = nums[i] | (nums[i + n] << 10);
        }

        int write = 2 * n - 1;
        for (int i = n - 1; i >= 0; i--) {
            int y = nums[i] >> 10;
            int x = nums[i] & 1023;
            nums[write--] = y;
            nums[write--] = x;
        }
        return nums;
    }
}

import java.util.ArrayDeque;
import java.util.Queue;

class Solution {
    public int[] shuffle(int[] nums, int n) {
        Queue<Integer> firstHalf = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            firstHalf.add(nums[i]);
        }

        int[] answer = new int[2 * n];
        int write = 0;
        for (int i = n; i < 2 * n; i++) {
            answer[write++] = firstHalf.remove();
            answer[write++] = nums[i];
        }
        return answer;
    }
}
